import React, { useEffect, useState } from 'react'

import './styles/news.css'


const fetchAllPosts = async (baseUrl, prefix = 'article-', extension = '.json') => {
  let posts = []
  let index = 1

  while (true) {
    const url = `${baseUrl}/${prefix}${index}${extension}`
    console.log(`Fetching: ${url}`)

    try {
      const response = await fetch(url)

      if (response.status === 404) {
        console.log(`No more posts after index ${index - 1}`)
        break
      }

      if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`)

      const data = await response.json()
      posts.unshift(data)
      index++
    } catch (error) {
      console.error(`Error fetching ${url}: `, error)
      break
    }
  }

  return posts
}


const News = () => {

  const [articles, setArticles] = useState([])

  useEffect(() => {
    const BASE_URL = 'https://raw.githubusercontent.com/psychdotcat/psychdotcat.github.io/refs/heads/gh-pages/articles'

    fetchAllPosts(BASE_URL).then(data => setArticles(data))
  }, [])

  const renderArticles = () => {
    return articles.map((article, index) => (
      <article key={index} className="article">
        {article.bannerImageUrl && (
          <img src={article.bannerImageUrl} alt={article.title} />
        )}
        <p><em>Published on: {article.date}</em></p>
        <h2>{article.title}</h2>
        <h4>{article.subtitle}</h4>
        <div dangerouslySetInnerHTML={{ __html: article.bodyHtml }} />
      </article>
    ))
  }

  return (
    <div className="news-articles">
      {renderArticles()}
    </div>
  )
}


export default News
